def parse_record(path):
    """Return dict with record number, portfolio key, role, entity, revision, and body text."""
    fn = os.path.basename(path)
    m = re.match(r'(\d+)_.*_source_export\.(md|txt|eml|csv|json|xml|html|pdf)$', fn)
    n = int(m.group(1))
    fmt = m.group(2)
    text = open(path, encoding='utf-8', errors='replace').read()
    rec = {'n': n, 'fmt': fmt, 'path': path}
    # Common fields
    for pat, key in [
        (r'PORTFOLIO KEY:\s*(CBP-001-\d+)', 'portfolio_key'),
        (r'EVIDENCE ROLE:\s*([A-Za-z_ ]+?)\n', 'role'),
        (r'ENTITY KEY:\s*(ENT-001-\d+)', 'entity'),
        (r'REVISION:\s*(REV-[\d.]+)', 'revision'),
        (r'RECORD: CB-DOC-001-(\d+)', 'record_id'),
    ]:
        mm = re.search(pat, text)
        if mm:
            rec[key] = mm.group(1).strip()
    # body: for txt/md/eml/html, find "NATIVE RECORD" section
    if fmt in ('md','txt','eml','html'):
        mm = re.search(r'(?:NATIVE RECORD\n|## Native record\n)(.*?)(?:SOURCE LINEAGE|## Source lineage|## Chronology|## Provenance|PROVENANCE|## Related native records)', text, re.S)
        if mm:
            rec['body'] = mm.group(1).strip()
    elif fmt == 'json':
        try:
            d = json.loads(text)
            rec['body'] = d.get('body','')
            rec['portfolio_key'] = d.get('portfolio_key')
            rec['role'] = d.get('evidence_role')
            rec['entity'] = d.get('immutable_entity_key')
            rec['revision'] = d.get('current_revision')
        except Exception as e:
            rec['body'] = 'JSONPARSEERR'
    elif fmt == 'xml':
        try:
            root = ET.fromstring(text)
            # generic: find text nodes
            parts = []
            for el in root.iter():
                if el.text and el.text.strip():
                    parts.append(el.text.strip())
            rec['body'] = ' | '.join(parts)
        except Exception as e:
            rec['body'] = 'XMLPARSEERR'
    elif fmt == 'csv':
        try:
            rows = list(csv.reader(text.splitlines()))
            rec['body'] = 'CSVROWS:' + str(len(rows))
        except Exception as e:
            rec['body'] = 'CSVERR'
    elif fmt == 'pdf':
        rec['body'] = 'PDF(binary)'
    return rec

