    if m: d['revision'] = m.group(1)
    else:
        m = re.search(r'REVISION:\s*(REV-[\d.]+)', text)
        if m: d['revision'] = m.group(1)
    # subject
    m = re.search(r'SUBJECT:\s*([^\n]+)', text)
    if m: d['subject'] = m.group(1).strip()
